{
  "name": "opencode-session-finder",
  "version": "1.1.1",
  "description": "OpenCode plugin that searches previous sessions from the command palette and gives the agent search_sessions and open_session tools",
  "author": {
    "name": "Pedro Pombeiro",
    "email": "pedropombeiro@users.noreply.github.com"
  },
  "type": "module",
  "main": "./dist/index.js",
  "exports": {
    ".": {
      "default": "./dist/index.js"
    },
    "./tui": {
      "default": "./dist/tui.js"
    }
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/pedropombeiro/opencode-plugins.git",
    "directory": "packages/session-finder"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "dist"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "session",
    "search",
    "history"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode/plugin": "^2.2.0",
    "solid-js": ">=1.9.0"
  }
}
